130	## Error Log (`src/error-log/`)
131	
132	### Types (`error-log.types.ts`)
133	
134	```typescript
135	type ErrorSeverity = 'error' | 'warning';
136	
137	interface ErrorLogContext {
138	    ProjectId?: string;
139	    WorkspaceId?: string;
140	    RepositoryId?: string;
141	}
142	
143	interface ErrorLogEntry {
144	    Id: number;             // Auto-incremented unique numeric identifier
145	    Timestamp: string;      // ISO 8601 UTC timestamp assigned by append()
146	    Severity: ErrorSeverity;
147	    Source: string;         // Subsystem or component that produced the entry
148	    Operation: string;      // Operation being performed when the error occurred
149	    Context: ErrorLogContext;
150	    Message: string;
151	    Details?: string;       // Optional structured detail (stack trace, raw output, etc.)
152	}
153	
154	interface ErrorLogStore extends BaseStore {
155	    Entries: ErrorLogEntry[];
156	}
157	
158	const DEFAULT_MAX_ERROR_LOG_ENTRIES = 500;  // Default FIFO eviction cap — overridden by AppConfig.maxErrorLogEntries
159	
160	interface ErrorLogListOptions {
161	    severity?: ErrorSeverity;   // Filter by severity; omit to return all
162	    source?: string;            // Exact-match filter on Source; omit to return all
163	    limit?: number;             // Max entries to return; omit to return all matching.
164	                                // limit=0 or negative → empty entries, total unaffected.
165	    offset?: number;            // Zero-based offset into filtered results (default: 0).
166	                                // offset ≥ total → empty entries, total unaffected.
167	                                // Negative offset treated as 0 (slice semantics).
168	}
169	
170	interface ErrorLogListResult {
171	    entries: ErrorLogEntry[];   // Paged entries (after filtering and pagination)
172	    total: number;              // Total matching entries before pagination (post-filter)
173	}
174	```
175	
176	### Manager (`error-log.manager.ts`)
